    showAlert: function(msg) {
        Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '알림',
                message : msg,
                alwaysOnTop : true,
                fn : function(btn) {
                    return;
                }
            });
    },

    onSelectRept: function() {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();

        var boWekmTmrdId = vm.get('tmrdInfo.boWekmTmrdId');

        Ext.Ajax.request({
            headers: {
                viewId : me.getViewId(),
                serviceId : 'BomWekWorkSvc.findOneBomWekWorkEmpInfo'
            },
            jsonData : {
                boWekmTmrdId : boWekmTmrdId,
            },
            scope : me,
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);
                var strdt = res.tmrdInfo.strdt;
                var edt = res.tmrdInfo.edt;

                var weekLabel = res.tmrdInfo.mnthWeekTmrdNm.substr(6);
                var dateLabel = strdt.substr(0,4) + '.' + strdt.substr(4,2) + '.' + strdt.substr(6,2) + '~' + edt.substr(0,4) + '.' + edt.substr(4,2) + '.' + edt.substr(6,2);

                refs.weekLabel.setHtml(weekLabel);
                refs.dateLabel.setHtml(dateLabel);

                vm.set('reptList',res.reptList);
                vm.set('tmrdInfo',res.tmrdInfo);
                vm.set('empInfo',res.empInfo);

                if(res.tmrdInfo.wrtrState == 'TRUE'){
                        if(res.tmrdInfo.leadBoWekmTmrdId == 0){
                            refs.writeBtn.setHidden(false);
                        }
                        else{
                            refs.writeBtn.setHidden(true);
                        }

                        Ext.Ajax.request({
                            headers: {
                                viewId : me.getViewId(),
                                serviceId : 'BomWekWorkSvc.saveBomWekWorkState' // 저장
                            },
                            jsonData : {
                                boWekmTmrdId : res.tmrdInfo.boWekmTmrdId
                            },
                            scope : me,
                            success : function(response) {
                                me.onSelect();
                            }
                        });
                }
                else{
                        refs.writeBtn.setHidden(true);
                        me.onSelect();
                }

            }
        });
    },

    onButtonTapLeft: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();


        var changeTmrdId = vm.get('tmrdInfo.lagBoWekmTmrdId');

        if(changeTmrdId !== 0){
            vm.set('tmrdInfo.boWekmTmrdId',changeTmrdId);
            me.onSelectRept();
        }
        else{
            Ext.Msg.alert('알림','이전 주차가 존재하지 않습니다.');
        }


    },

    onButtonTapRight: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();


        var changeTmrdId = vm.get('tmrdInfo.leadBoWekmTmrdId');

        if(changeTmrdId !== 0){
            vm.set('tmrdInfo.boWekmTmrdId',changeTmrdId);
            me.onSelectRept();
        }
        else{
            Ext.Msg.alert('알림','다음 주차가 존재하지 않습니다.');
        }

    },

    onContainerResize: function(element, info, eOpts) {
        element.updateLayout();
        this.getView().updateLayout();
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();


        vm.set('initData', component.config.data);	// 초기데이터

        me.onSelectRept();

    },

    onButtonTapWrite: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            naviView = me.getView().up('navigationview');

        var maxCnt = Properties.getProperty('BOM_MAX_WEEK_WORK');

        if(!vm.get('tmrdInfo.empCnt')){
            me.showAlert('주간 주요업무 작성 대상자가 아닙니다.');
            return false;
        }
        if(vm.get('tmrdInfo.wrtrState') == 'FALSE' && (button.reference == 'writeBtn')){
            me.showAlert('주간 주요업무 작성기간이 아닙니다.' );
            return false;
        }

        if((vm.get('reptList').length>= maxCnt) && (button.reference == 'writeBtn' )){
            me.showAlert('작성은 최대 ' + maxCnt + '개까지 가능합니다' );
            return false;
        }

        var boWekmTmrdId = vm.get('tmrdInfo.boWekmTmrdId');
        var boWekdTmrdEmpId = vm.get('empInfo.boWekdTmrdEmpId');
        var tmrdInfo = vm.get('tmrdInfo');
        var empInfo = vm.get('empInfo');
        var popupData = {
            boWekmTmrdId : boWekmTmrdId,
            boWekdTmrdEmpId : boWekdTmrdEmpId,
            tmrdInfo : tmrdInfo,
            empInfo : empInfo,
        };

        // onSelect 함수에서 만들어지는 reference와 itemId로 컨테이너 구분

        var ctnNum = button.getItemId().replace(/btn/g,'');
        if(button.reference != 'writeBtn'){
            var reptData = vm.get('reptList')[ctnNum];
            reptData.strdt = DateUtils.parseDate(reptData.strdt);
            reptData.edt = DateUtils.parseDate(reptData.edt);
            popupData.reptData = reptData;
        }

        Ext.Ajax.request({
            headers: {
                viewId : me.getViewId(),
                serviceId : 'BomWekWorkSvc.findCodelist' // 사무분담 프로젝트 조회
            },
            jsonData : {
                boWekmTmrdId : boWekmTmrdId,
            },
            scope : me,
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);
                popupData.rolList = res.rolList;
                popupData.prjList = res.prjList;
                popupData.bizList = res.bizList;

                me.PUSH_VIEW(naviView, {
                    menuId  : 'BomWekWork02M',
                    title   : '주간주요업무',
                    isSubView : true,
                    parentView : me.getView(),
                    popupData : Ext.clone(popupData)
                });
                //         var win = Ext.create('BomWekWork51M', Ext.clone(popupData));
                //         me.mon(win, 'complete', function() {
                //             me.onSelectRept();
                //         }, me);
                //         win.show();
            }
        });



    }

